  const wx = sx+w2x, wy = sy+w2y;
  const src = [
    [140+Math.sin(t*0.5)*90, 70+Math.cos(t*0.35)*45, 0.075, 2.1, 1.0],
    [340+Math.cos(t*0.45)*90, 170+Math.sin(t*0.6)*50, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*130, 110+Math.cos(t*0.42+1)*80, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*70, 190+Math.sin(t*0.55+3)*55, 0.11, 1.4, 0.85],
    [380+Math.sin(t*0.38+4)*80, 50+Math.cos(t*0.8+2)*65, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.32+5)*110, 210+Math.sin(t*0.5)*70, 0.085, 2.0, 0.95],
    [300+Math.sin(t*0.6+3)*60, 40+Math.cos(t*0.48+4)*50, 0.1, 1.6, 0.88],
    [60+Math.cos(t*0.42+2)*75, 130+Math.sin(t*0.65+1)*60, 0.07, 2.3, 1.02]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp,w]=src[i];
    const d=Math.sqrt((wx-sX)**2+(wy-sY)**2);
    const a=Math.sin(d*f-t*sp), inh=Math.sin(d*f*0.65+t*sp*0.55+1.7);
    aS+=a*w; iS+=inh*w;
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2,f2,sp2]=src[j];
      const d2=Math.sqrt((wx-sX2)**2+(wy-sY2)**2);
      cross+=Math.sin(d*f+d2*f2-t*(sp+sp2)*0.5)*0.04;
    }
  }
  const act=aS/8, inh=iS/8;
  const n1=Math.sin(wx*0.035+wy*0.022+t*0.9), n2=Math.sin(wx*0.028-wy*0.038+t*1.2);
  const n3=Math.sin((wx+wy)*0.11+t*2.8)*0.25, n4=Math.sin((wx-wy)*0.095-t*2.2)*0.25;
  const n5=Math.sin(wx*0.06+wy*0.04+t*1.6)*0.15, n6=Math.sin(wx*0.045-wy*0.055-t*1.4)*0.15;
  const bg=(n1+n2)/2+n3+n4+n5+n6;
