  const sp2=Math.sin(dist*0.08-ang*2-t*2.5)*0.15+Math.sin(dist*0.06+ang*5-t*0.8)*0.1;
  const spiral=sp1+sp2;
  const vx=wx*0.12, vy=wy*0.12;
  const vor=Math.min(Math.abs(Math.sin(vx)*Math.cos(vy)),Math.abs(Math.cos(vx*1.3)*Math.sin(vy*1.1)));
  const cell=Math.sin(vor*8+t*0.5)*0.25;
  const pulse=Math.sin(t*0.4)*0.08;
  const react=Math.tanh((act-inh*0.65+bg*0.28+spiral+cross+cell+pulse)*2.0);
  const sharp=react>0.6?Math.pow((react-0.6)/0.4,0.7):react<-0.6?-Math.pow((-react-0.6)/0.4,0.7):0;
  const smooth=react*0.65+sharp*0.35;
  const edge=Math.abs(react)>0.65?1.2+Math.sin(t*3)*0.05:1.0;
  const lum=0.82+Math.sin(smooth*Math.PI)*0.18;
  const v=smooth*0.5+0.5;
