  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge;
  const b=(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge;
  return [Math.min(255,r)|0, Math.min(255,g)|0, Math.min(255,b)|0];
